def preencher_familia(apps, schema_editor):
    """Domínio e caminho vêm do padrão de onde saiu a amostra; a versão passa a ser numerada
    dentro da família, na ordem de criação (antes era por padrão, e cada padrão tinha a sua v1)."""
    SchemaPagina = apps.get_model("artifacts", "SchemaPagina")
    familias = {}
    for s in SchemaPagina.objects.select_related("padrao").order_by("created_at"):
        s.dominio, s.caminho = s.padrao.domain, s.padrao.path_pattern
        chave = (s.tenant_id, s.dominio, s.caminho)
        familias[chave] = familias.get(chave, 0) + 1
        s.versao = familias[chave]
        s.save(update_fields=["dominio", "caminho", "versao"])


